"""The self-test half of the ECG dataset `data/v1`, regenerated by spicefault alone.

Circuit, healthy population, faults, seeding, simulation, measurements and waveform
all come from spicefault here; `ecgfd` only supplies the nominal netlist and the
numbers of its configuration. The dataset location comes from ECGFD_DATA.
"""

import json
import os
from pathlib import Path

import numpy as np
import pandas as pd
import pytest
from ecgfd.config import REPO_ROOT

from ecg_adapter import service_experiment
from spicefault.experiments import run_chunks, simulate_sample

pytestmark = [pytest.mark.ecgfd, pytest.mark.ngspice, pytest.mark.baseline_data]

DATA = Path(os.environ.get("ECGFD_DATA", REPO_ROOT / "data" / "v1"))
PER_KIND = 3
RTOL, ATOL = 1e-9, 1e-15


@pytest.fixture(scope="module")
def stored(cfg):
    folder = DATA / cfg["circuit"]
    if not (folder / "samples.parquet").exists():
        pytest.skip(f"no baseline dataset in {folder}")
    manifest = json.loads((folder / "manifest.json").read_text())
    df = pd.read_parquet(folder / "samples.parquet")
    return manifest["config"], df, np.load(folder / "waveforms.npy", mmap_mode="r")


def test_plan_is_the_sample_list_of_the_dataset(stored):
    cfg, df, _ = stored
    experiment = service_experiment(cfg)
    plan = experiment.plan()
    assert len(plan) == len(df)
    picked = df.iloc[:: len(df) // 500]
    for row in picked.itertuples():
        sample = plan[row.sample_id]
        assert (sample.fault_index, sample.replica) == (row.condition_index, row.replica)
        assert experiment.fault_id(sample) == row.condition


def test_regenerated_cases_match_the_dataset(stored, tmp_path):
    cfg, df, waveforms = stored
    experiment = service_experiment(cfg)
    plan = experiment.plan()

    # a few cases of every fault kind, healthy included. The value injected by an
    # `ina_cmrr` fault depends on the drawn sign, so those are built per sample by the
    # adapter and are not covered here
    candidates = df[df["kind"] != "ina_cmrr"]
    picked = candidates.groupby("kind", sort=True).sample(PER_KIND, random_state=1)
    ids = sorted(picked["sample_id"])
    stems = run_chunks(
        [plan[i] for i in ids], simulate_sample, experiment, tmp_path,
        experiment.waveform.n_points, workers=4, progress=False,
    )
    ours = pd.read_parquet(stems[0].with_suffix(".parquet"))
    theirs = df.set_index("sample_id").loc[ids].reset_index(drop=True)
    assert (ours["status"] == "SUCCESS").all() and theirs["sim_ok"].all()
    assert list(ours["fault_id"]) == list(theirs["condition"])
    assert list(ours["electrode_kind"]) == list(theirs["electrode_kind"])

    features = [m.name for m in experiment.measurements]
    assert features == [c for c in df.columns if c.startswith(("dc_", "acd_", "acc_", "zlo_"))]
    pd.testing.assert_frame_equal(
        ours[features], theirs[features], check_exact=False, rtol=RTOL, atol=ATOL
    )
    assert np.array_equal(np.load(stems[0].with_suffix(".npy")), waveforms[ids])
    worst = float(np.abs(ours[features].to_numpy() - theirs[features].to_numpy()).max())
    print(f"\n{cfg['circuit']}: {len(ids)} cases, largest difference {worst}")

    # realised values: the dataset records them after the fault, spicefault before it
    healthy = (theirs["kind"] == "healthy").to_numpy()
    for (component, parameter), column in parameter_columns(ours, theirs).items():
        ours_column = ours[f"p_{component}_{parameter}"]
        assert np.array_equal(ours_column[healthy], theirs.loc[healthy, column]), column
    assert healthy.sum() == PER_KIND


def parameter_columns(ours: pd.DataFrame, theirs: pd.DataFrame) -> dict[tuple[str, str], str]:
    """(component, parameter) of spicefault -> column of the ECG dataset, where both exist."""
    found = {}
    for column in theirs.columns:
        if not column.startswith("p_"):
            continue
        name = column[2:]
        for candidate in (
            (name, "value"),  # p_R1 -> R1.value
            (f"X{name.rsplit('_', 1)[0]}", name.rsplit("_", 1)[-1]),  # p_U2_vos -> XU2.vos
        ):
            if f"p_{candidate[0]}_{candidate[1]}" in ours.columns:
                found[candidate] = column
    return found
